ruleBody:
PREFIX om: <https://open-metadata.org/ontology/>
CONSTRUCT {
  ?descendant om:hasTag ?tag .
  ?descendant om:inferredTagSource ?ancestor
}
WHERE {
  {
    ?ancestor a om:DatabaseSchema ;
              om:hasTag ?tag .
    ?descendant om:belongsToSchema ?ancestor .
  } UNION {
    ?ancestor a om:Table ;
              om:hasTag ?tag .
    ?ancestor om:hasColumn ?descendant .
  }
}

PREFIX om: <https://open-metadata.org/ontology/>
CONSTRUCT {
  ?downstream om:hasTag ?piiTag .
  ?downstream om:inferredTagSource ?upstream
}
WHERE {
  ?upstream om:hasTag ?piiTag .
  ?piiTag om:tagFQN ?fqn .
  FILTER(STRSTARTS(?fqn, "PII."))
  ?colLineage om:fromColumn ?upstream ;
              om:toColumn ?downstream .
}

PREFIX om: <https://open-metadata.org/ontology/>
CONSTRUCT { ?column om:belongsToDomain ?domain }
WHERE {
  ?table a om:Table ;
         om:belongsToDomain ?domain ;
         om:hasColumn ?column .
}
